                FpGidCps(g, reg, Fontextra.CffExpertsubCharset[gid]);
            }
            return emon.Port.CellsAt(g, reg);
        }
        sid = FpCharsetSid(d, @base + cs, ng, gid);
        return FpSidCps(g, reg, tbl, d, @base, sid, zapf);
    }
    internal static int FpCff(emon.Port.Cells g, int reg, int tbl, byte[] d, int @base, int zapf) {
        // A CFF font's built-in encoding. -1 when it is not a (name-keyed) CFF font.
        int sc = tbl + Scr;
        int hdr = FpU8(d, @base + 2);
        int nidx = @base + hdr;
        int tidx = FpIdxEnd(d, nidx);
        int sidx = FpIdxEnd(d, tidx);
        int ts = 0;
        int te = 0;
        int enc = 0;
        int cnt = 0;
        int code = 0;
        int gd = 0;
        int fmt = 0;
        int pos = 0;
        int j = 0;
        int nl = 0;
        int ns = 0;
        int cso = 0;
        if (FpU8(d, @base) != 1) {
            return -1;
        }
        if (hdr < 4) {
            return -1;
        }
        emon.Port.CellsSet(g, sc + SKind, 1);
        if (FpIdxCount(d, tidx) < 1) {
            return -1;
        }
        ts = FpIdxStart(d, tidx, 0);
        te = FpIdxStart(d, tidx, 1);
        if ((te < ts) || ((te - ts) > 65536)) {
            return -1;
        }
        emon.Port.CellsSet(g, sc + SStr, sidx);
        FpDict(g, tbl, d, ts, te);
        if (emon.Port.CellsAt(g, sc + SCid) == 1) {
            return -1;
        }
        cso = emon.Port.CellsAt(g, sc + SCharstr);
        if (cso <= 0) {
            return -1;
        }
        emon.Port.CellsSet(g, sc + SNg, FpIdxCount(d, @base + cso));
        enc = emon.Port.CellsAt(g, sc + SEnc);
        if (enc == 0) {
            return FpFillGids(g, reg, tbl, 0);
        }
        if (enc == 1) {
            code = 0;
            while (code < 256) {
                gd = Fontextra.CffExpertEnc[code];
                if (gd >= 0) {
                    FpGidCps(g, reg, gd);
                    cnt += FpPut(g, reg, tbl, code, 2);
                }
                code += 1;
            }
            return cnt;
        }
        pos = @base + enc;
        fmt = FpU8(d, pos);
        if ((fmt % 128) == 0) {
            nl = FpU8(d, pos + 1);
            j = 0;
            while (j < nl) {
                code = FpU8(d, (pos + 2) + j);
                FpGlyphCps(g, reg, tbl, d, @base, j + 1, zapf);
                cnt += FpPut(g, reg, tbl, code, 2);
                j += 1;
            }
            pos = (pos + 2) + nl;
        }
        if ((fmt % 128) == 1) {
            nl = FpU8(d, pos + 1);
            pos += 2;
            gd = 1;
            j = 0;
            while (j < nl) {
                ns = 0;
                while (ns <= FpU8(d, pos + 1)) {
                    code = FpU8(d, pos) + ns;
                    if (code <= 255) {
                        FpGlyphCps(g, reg, tbl, d, @base, gd, zapf);
                        cnt += FpPut(g, reg, tbl, code, 2);
                    }
                    gd += 1;
                    ns += 1;
                }
                pos += 2;
                j += 1;
            }
        }
        if (fmt >= 128) {
            nl = FpU8(d, pos);
            pos += 1;
            j = 0;
            while (j < nl) {
                code = FpU8(d, pos);
                FpSidCps(g, reg, tbl, d, @base, FpU16(d, pos + 1), zapf);
                cnt += FpPut(g, reg, tbl, code, 2);
                pos += 3;
                j += 1;
            }
        }
        return cnt;
    }
    internal static int FpSfntStart(byte[] d) {
        // The offset of the table directory: 0, or the first font of a collection; -1
        // when the data is no sfnt.
        int v = FpU32(d, 0);
        if (v == 65536) {
            return 0;
        }
        if ((FpU8(d, 0) == 116) && ((FpU8(d, 1) == 114) && ((FpU8(d, 2) == 117) && (FpU8(d, 3) == 101)))) {
            return 0;
        }
        if ((FpU8(d, 0) == 79) && ((FpU8(d, 1) == 84) && ((FpU8(d, 2) == 84) && (FpU8(d, 3) == 79)))) {
            return 0;
        }
        if ((FpU8(d, 0) == 116) && ((FpU8(d, 1) == 116) && ((FpU8(d, 2) == 99) && (FpU8(d, 3) == 102)))) {
            return FpU32(d, 12);
        }
        return -1;
    }
    internal static int FpSfntTable(byte[] d, int start, int t0, int t1, int t2, int t3) {
        // The offset of the table tagged t0 t1 t2 t3, or -1.
        int nt = FpU16(d, start + 4);
        int i = 0;
        int r = 0;
        while ((i < nt) && (i < 200)) {
            r = (start + 12) + (i * 16);
            if ((FpU8(d, r) == t0) && ((FpU8(d, r + 1) == t1) && ((FpU8(d, r + 2) == t2) && (FpU8(d, r + 3) == t3)))) {
                if (FpIn(d, FpU32(d, r + 8)) == 1) {
                    return FpU32(d, r + 8);
                }
                return -1;
            }
            i += 1;
        }
        return -1;
    }
    internal static int FpCmapFind(emon.Port.Cells g, int tbl, byte[] d, int cm) {
        // Choose the cmap subtables: (3,0), (1,0), and the best Unicode one ((3,10), (3,1),
        // (0,x)) into the scratch cells (the absolute offsets, 0 none).
        int sc = tbl + Scr;
        int nt = FpU16(d, cm + 2);
        int i = 0;
        int r = 0;
        int plat = 0;
        int enc = 0;
        int off = 0;
        int rank = 0;
        int best = 0;
        emon.Port.CellsSet(g, sc + SC30, 0);
        emon.Port.CellsSet(g, sc + SC10, 0);
        emon.Port.CellsSet(g, sc + SUni, 0);
        while ((i < nt) && (i < 64)) {
            r = (cm + 4) + (i * 8);
            plat = FpU16(d, r);
            enc = FpU16(d, r + 2);
            off = FpU32(d, r + 4);
            if (FpIn(d, cm + off) == 1) {
                off = cm + off;
                if ((plat == 3) && (enc == 0)) {
                    emon.Port.CellsSet(g, sc + SC30, off);
                }
                if ((plat == 1) && (enc == 0)) {
                    emon.Port.CellsSet(g, sc + SC10, off);
                }
                rank = 0;
                if (plat == 0) {
                    rank = 1;
                }
                if ((plat == 3) && (enc == 1)) {
                    rank = 2;
                }
                if ((plat == 3) && (enc == 10)) {
                    rank = 3;
                }
                if (rank > best) {
                    best = rank;
                    emon.Port.CellsSet(g, sc + SUni, off);
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int FpCmapGet(byte[] d, int sub, int code) {
        // The glyph index a cmap subtable (formats 0, 4, 6, 12) gives a code; 0 none.
        int fmt = FpU16(d, sub);
        int lo = 0;
        int hi = 0;
        int mid = 0;
        int segx2 = 0;
        int ec = 0;
        int sc = 0;
        int delta = 0;
        int ro = 0;
        int ra = 0;
        int gd = 0;
        int first = 0;
        int cnt = 0;
        if (code < 0) {
            return 0;
        }
        if (fmt == 0) {
            if (code > 255) {
                return 0;
            }
            return FpU8(d, (sub + 6) + code);
        }
        if (fmt == 6) {
            first = FpU16(d, sub + 6);
            cnt = FpU16(d, sub + 8);
            if ((code >= first) && (code < (first + cnt))) {
                return FpU16(d, (sub + 10) + ((code - first) * 2));
            }
            return 0;
        }
        if (fmt == 4) {
            if (code > 65535) {
                return 0;
            }
            segx2 = FpU16(d, sub + 6);
            hi = (segx2 / 2) - 1;
            while (lo <= hi) {
                mid = lo + ((hi - lo) / 2);
                ec = FpU16(d, (sub + 14) + (mid * 2));
                if (ec < code) {
                    lo = mid + 1;
                } else {
                    sc = FpU16(d, ((sub + 16) + segx2) + (mid * 2));
                    if (sc > code) {
                        hi = mid - 1;
                    } else {
                        delta = FpU16(d, ((sub + 16) + (segx2 * 2)) + (mid * 2));
                        ra = ((sub + 16) + (segx2 * 3)) + (mid * 2);
                        ro = FpU16(d, ra);
                        if (ro == 0) {
                            return (code + delta) % 65536;
                        }
                        gd = FpU16(d, (ra + ro) + ((code - sc) * 2));
                        if (gd == 0) {
                            return 0;
                        }
                        return (gd + delta) % 65536;
                    }
                }
            }
            return 0;
        }
        if (fmt == 12) {
            hi = FpU32(d, sub + 12) - 1;
            if (hi > 1000000) {
                hi = 1000000;
            }
            while (lo <= hi) {
                mid = lo + ((hi - lo) / 2);
                sc = FpU32(d, (sub + 16) + (mid * 12));
                ec = FpU32(d, ((sub + 16) + (mid * 12)) + 4);
                if (ec < code) {
                    lo = mid + 1;
                } else if (sc > code) {
                    hi = mid - 1;
                } else {
                    return FpU32(d, ((sub + 16) + (mid * 12)) + 8) + (code - sc);
                }
            }
            return 0;
        }
        return 0;
    }
    internal static int FpCmapRev(emon.Port.Cells g, int tbl, byte[] d, int sub, int gid) {
        // The smallest code a cmap subtable maps to glyph `gid` (formats 0, 4, 6, 12), or -1.
        // Scanning is bounded by the font's step budget.
        int sc = tbl + Scr;
        int fmt = FpU16(d, sub);
        int i = 0;
        int n = 0;
        int segx2 = 0;
        int st = 0;
        int en = 0;
        int delta = 0;
        int ro = 0;
        int ra = 0;
        int cp = 0;
        int gv = 0;
        int first = 0;
        if (gid <= 0) {
            return -1;
        }
        if (fmt == 0) {
            while (i < 256) {
                if (FpU8(d, (sub + 6) + i) == gid) {
                    return i;
                }
                i += 1;
            }
            return -1;
        }
        if (fmt == 6) {
            first = FpU16(d, sub + 6);
            n = FpU16(d, sub + 8);
            while (i < n) {
                if (FpU16(d, (sub + 10) + (i * 2)) == gid) {
                    return first + i;
                }
                i += 1;
            }
            return -1;
        }
        if (fmt == 4) {
            segx2 = FpU16(d, sub + 6);
            n = segx2 / 2;
            while (i < n) {
                en = FpU16(d, (sub + 14) + (i * 2));
                st = FpU16(d, ((sub + 16) + segx2) + (i * 2));
                delta = FpU16(d, ((sub + 16) + (segx2 * 2)) + (i * 2));
                ra = ((sub + 16) + (segx2 * 3)) + (i * 2);
                ro = FpU16(d, ra);
                if ((st <= en) && (st != 65535)) {
                    if (ro == 0) {
                        cp = (gid + (65536 - delta)) % 65536;
                        if ((cp >= st) && (cp <= en)) {
                            return cp;
                        }
                    } else {
                        cp = st;
                        while (cp <= en) {
                            emon.Port.CellsSet(g, sc + SBudget, emon.Port.CellsAt(g, sc + SBudget) - 1);
                            if (emon.Port.CellsAt(g, sc + SBudget) < 0) {
                                return -1;
                            }
                            gv = FpU16(d, (ra + ro) + ((cp - st) * 2));
                            if (gv != 0) {
                                if (((gv + delta) % 65536) == gid) {
                                    return cp;
                                }
                            }
                            cp += 1;
                        }
                    }
                }
                i += 1;
            }
            return -1;
        }
        if (fmt == 12) {
            n = FpU32(d, sub + 12);
            if (n > 100000) {
                n = 100000;
            }
            while (i < n) {
                st = FpU32(d, (sub + 16) + (i * 12));
                en = FpU32(d, ((sub + 16) + (i * 12)) + 4);
                gv = FpU32(d, ((sub + 16) + (i * 12)) + 8);
                if ((gid >= gv) && ((gid - gv) <= (en - st))) {
                    return st + (gid - gv);
                }
                i += 1;
            }
            return -1;
        }
        return -1;
    }
    internal static int FpPostName(emon.Port.Cells g, int reg, byte[] d, int post, int gid, int zapf) {
        // The code points of glyph `gid`'s name in the `post` table (formats 1 and 2).
        int ver = FpU32(d, post);
        int ng = 0;
        int idx = 0;
        int p = 0;
        int k = 0;
        int ln = 0;
        emon.Port.CellsSet(g, reg, 0);
        if ((post < 0) || (gid < 0)) {
            return 0;
        }
        if (ver == 65536) {
            if (gid >= 258) {
                return 0;
            }
            if (Fontextra.MacGlyphOrder[gid] >= 0) {
                FpGidCps(g, reg, Fontextra.MacGlyphOrder[gid]);
            }
            return emon.Port.CellsAt(g, reg);
        }
        if (ver == 131072) {
            ng = FpU16(d, post + 32);
            if (gid >= ng) {
                return 0;
            }
            idx = FpU16(d, (post + 34) + (gid * 2));
            if (idx < 258) {
                if (Fontextra.MacGlyphOrder[idx] >= 0) {
                    FpGidCps(g, reg, Fontextra.MacGlyphOrder[idx]);
                }
                return emon.Port.CellsAt(g, reg);
            }
            p = (post + 34) + (ng * 2);
            k = 0;
            while ((k < (idx - 258)) && (k < 70000)) {
                if (FpIn(d, p) == 0) {
                    return 0;
                }
                p += 1 + FpU8(d, p);
                k += 1;
            }
            ln = FpU8(d, p);
            if (FpIn(d, p + ln) == 0) {
                return 0;
            }
            return FpNameCps(g, reg, d, p + 1, (p + 1) + ln, zapf);
        }
        return 0;
    }
    internal static int FpGlyphUnicode(emon.Port.Cells g, int reg, int tbl, byte[] d, int gid, int zapf) {
        // What glyph `gid` of a TrueType font is: the font's Unicode cmap read backwards, else
        // its post name. 0: nothing, else the `how` (2 cmap, 3 name); the code points are in the
        // registers.
        int sc = tbl + Scr;
        int uni = emon.Port.CellsAt(g, sc + SUni);
        int post = emon.Port.CellsAt(g, sc + SPost);
        int cp = 0;
        emon.Port.CellsSet(g, reg, 0);
        if (uni > 0) {
            cp = FpCmapRev(g, tbl, d, uni, gid);
            if ((cp > 0) && ((cp != 65535) && ((cp < 55296) || (cp > 57343)))) {
                FpAdd(g, reg, cp);
                return 2;
            }
        }
        if (post > 0) {
            if (FpPostName(g, reg, d, post, gid, zapf) > 0) {
                return 3;
            }
        }
        return 0;
    }
    internal static int FpSfnt(emon.Port.Cells g, int reg, int tbl, byte[] d, int start, int zapf) {
        // A TrueType or OpenType font's codes. A font with a `CFF ` table is read as CFF;
        // else each code goes through the symbolic-font rule. -1 when there is no cmap.
        int sc = tbl + Scr;
        int cff = FpSfntTable(d, start, 67, 70, 70, 32);
        int cm = FpSfntTable(d, start, 99, 109, 97, 112);
        int code = 0;
        int gd = 0;
        int how = 0;
        int cnt = 0;
        int c30 = 0;
        int c10 = 0;
        if (cff >= 0) {
            return FpCff(g, reg, tbl, d, cff, zapf);
        }
        if (cm < 0) {
            return -1;
        }
        emon.Port.CellsSet(g, sc + SPost, FpSfntTable(d, start, 112, 111, 115, 116));
        if (emon.Port.CellsAt(g, sc + SPost) < 0) {
            emon.Port.CellsSet(g, sc + SPost, 0);
        }
        FpCmapFind(g, tbl, d, cm);
        c30 = emon.Port.CellsAt(g, sc + SC30);
        c10 = emon.Port.CellsAt(g, sc + SC10);
        if ((c30 == 0) && (c10 == 0)) {
            return -1;
        }
        emon.Port.CellsSet(g, sc + SKind, 2);
        while (code < 256) {
            gd = 0;
            if (c30 > 0) {
                gd = FpCmapGet(d, c30, 61440 + code);
                if (gd == 0) {
                    gd = FpCmapGet(d, c30, 61696 + code);
                }
                if (gd == 0) {
                    gd = FpCmapGet(d, c30, 61952 + code);
                }
                if (gd == 0) {
                    gd = FpCmapGet(d, c30, code);
                }
            }
            if ((gd == 0) && (c10 > 0)) {
                gd = FpCmapGet(d, c10, code);
            }
            if (gd > 0) {
                how = FpGlyphUnicode(g, reg, tbl, d, gd, zapf);
                if (how > 0) {
                    cnt += FpPut(g, reg, tbl, code, how);
                }
            }
            code += 1;
        }
        return cnt;
    }
    public static int FpSimple(emon.Port.Cells g, int reg, int tbl, byte[] d, int zapf) {
        // Read a font program's built-in encoding into the table at `tbl` of `g`, which the
        // caller made 1552 cells long (`T_SIZE` + 16 of scratch); the registers are `reg`.
        // Answers the count of codes the program gave a value (-1: nothing recognised).
        int start = 0;
        FpClear(g, tbl);
        if (emon.Port.BlobLen(d) < 4) {
            return -1;
        }
        if ((FpU8(d, 0) == 128) || ((FpU8(d, 0) == 37) && (FpU8(d, 1) == 33))) {
            return FpT1(g, reg, tbl, d, zapf);
        }
        start = FpSfntStart(d);
        if (start >= 0) {
            return FpSfnt(g, reg, tbl, d, start, zapf);
        }
        if ((FpU8(d, 0) == 1) && (FpU8(d, 1) == 0)) {
            return FpCff(g, reg, tbl, d, 0, zapf);
        }
        return -1;
    }
    public static int FpTableSize() {
        return TSize + 16;
    }
    public static int FpKind(emon.Port.Cells g, int tbl) {
        // After `fp-simple`: 1 when the program names its glyphs (Type 1, CFF: what it does not
        // name, it does not draw), 2 for a TrueType font, 0 when nothing was recognised.
        return emon.Port.CellsAt(g, (tbl + Scr) + SKind);
    }
}
